import pytest
from unittest.mock import patch, MagicMock

# Assuming 'app.auth' is the module where login and user are defined
# And 'app.jwt_utils' is where create_jwt is defined

@patch('app.auth.create_jwt')
@patch('app.auth.user', new_callable=MagicMock)
def test_login_success_returns_jwt(mock_user, mock_create_jwt):
    mock_user.id = 'test_user_123'
    mock_create_jwt.return_value = 'mock_jwt_token'

    from app.auth import login
    result = login()

    mock_create_jwt.assert_called_once_with('test_user_123')
    assert result == {'access_token': 'mock_jwt_token'}
